CREATE TABLE t_p25384465_short_number_service.phone_numbers (
  id SERIAL PRIMARY KEY,
  number VARCHAR(50) NOT NULL,
  name VARCHAR(200) NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  operator VARCHAR(50) NOT NULL DEFAULT 'Универсальный',
  category VARCHAR(100) NOT NULL DEFAULT 'Коммерческие',
  procedure TEXT,
  organization VARCHAR(200),
  device_access VARCHAR(20),
  industry VARCHAR(100),
  suggested_by VARCHAR(200),
  sort_order INT NOT NULL DEFAULT 0,
  updated_at TIMESTAMP DEFAULT NOW()
);


SELECT setval('t_p25384465_short_number_service.phone_numbers_id_seq', 100);
